sys_variable_value.value:
(function execute(inputs, outputs) {
    var scheduleId = inputs.scheduleSysId;
    var raisedparticipants = 0;

    if (!scheduleId) {
        gs.warn("[Raise max participants] Missing scheduleSysId input.");
        outputs.raisedparticipants = 0;
        return;
    }

    var schedule = new GlideRecord("x_1805892_compan_0_schedule");
    if (!schedule.get(scheduleId)) {
        gs.warn("[Raise max participants] Schedule not found: " + scheduleId);
        outputs.raisedparticipants = 0;
        return;
    }

    var count = new GlideAggregate("x_1805892_compan_0_enrollment");
    count.addQuery("schedule", scheduleId);
    count.addQuery("state", "IN", "1,3");
    count.addAggregate("COUNT");
    count.query();

    if (count.next()) {
        raisedparticipants = parseInt(count.getAggregate("COUNT"), 10);
    }

    var maxCap = parseInt(schedule.getValue("max_participants"), 10);

    if (raisedparticipants > maxCap) {
        schedule.setValue("max_participants", raisedparticipants);
        schedule.update();
        gs.info("[Raise max participants] Max participants increased from " + maxCap + " to " + raisedparticipants);
    }

    outputs.raisedparticipants = raisedparticipants;

})(inputs, outputs);

